/**
 * ============================================================
 * FILE PATH / NAME
 * ============================================================
 *
 * scripts/feature_turn/turn-commands.js
 */

/**
 * ============================================================
 * FRAME HELM TURN -- COMMAND SURFACE
 * ============================================================
 *
 * ROLE:
 *   Provides the public command/query surface for the canonical
 *   Frame Helm Turn state manager.
 *
 * PURPOSE:
 *   Keep mutation wrappers and canonical state accessors outside
 *   turn-feature.js so that turn-feature.js can remain the public
 *   feature-package declaration surface.
 *
 * OWNS:
 *   - Begin-turn command delegation.
 *   - Ensure-turn command delegation.
 *   - End-turn command delegation.
 *   - Clear-turn command delegation.
 *   - Action-legality command delegation.
 *   - Action-use command delegation.
 *   - Transitional movement command delegation.
 *   - Speed mutation command delegation.
 *   - Overcharge command delegation.
 *   - Canonical current-state lookup.
 *   - Canonical manager lookup.
 *   - Canonical state snapshot lookup.
 *
 * DOES NOT OWN:
 *   - FrameHelmTurnState implementation.
 *   - FrameHelmTurnStateManager implementation.
 *   - Combat synchronization.
 *   - Runtime dependency bindings.
 *   - Feature declaration.
 *   - UI rendering implementation.
 */


/* ============================================================
   Imports
   ============================================================ */

import {
  frameHelmTurnState
} from "./turn-state-manager.js";


/* ============================================================
   Canonical Turn queries
   ============================================================ */

/**
 * Returns the currently-active Frame Helm turn state without
 * creating a turn when none exists.
 */
export function getCurrentFrameHelmTurn() {
  return (
    frameHelmTurnState.current ??
    null
  );
}


/**
 * Returns the canonical Frame Helm turn-state manager.
 *
 * This accessor is intentionally explicit. Consumers which need
 * manager operations must not mistake the current Turn state for
 * the manager which owns it.
 */
export function getFrameHelmTurnStateManager() {
  return frameHelmTurnState;
}


/**
 * Returns a serializable snapshot of the active Turn state.
 */
export function getFrameHelmTurnSnapshot() {
  return (
    frameHelmTurnState.snapshot()
  );
}


/* ============================================================
   Turn lifecycle commands
   ============================================================ */

export function beginFrameHelmTurn(
  context = {}
) {
  return (
    frameHelmTurnState.beginTurn(
      context
    )
  );
}


export function ensureFrameHelmTurn(
  context = {}
) {
  return (
    frameHelmTurnState.ensureTurn(
      context
    )
  );
}


export function endFrameHelmTurn() {
  return (
    frameHelmTurnState.endTurn()
  );
}


export function clearFrameHelmTurn() {
  return (
    frameHelmTurnState.clear()
  );
}


/* ============================================================
   Turn action commands
   ============================================================ */

export function canUseFrameHelmTurnAction(
  actionId,
  options
) {
  return (
    frameHelmTurnState
      .ensureTurn()
      .canUseAction(
        actionId,
        options
      )
  );
}


export function useFrameHelmTurnAction(
  actionId,
  options
) {
  const result =
    frameHelmTurnState
      .ensureTurn()
      .useAction(
        actionId,
        options
      );


  frameHelmTurnState
    .renderApplication();


  return result;
}


/* ============================================================
   Transitional movement commands
   ============================================================ */

/**
 * Movement accounting currently remains available through the
 * Turn state while its second-stage extraction is completed.
 */
export function spendFrameHelmTurnMovement(
  distance
) {
  const result =
    frameHelmTurnState
      .ensureTurn()
      .spendMovement(
        distance
      );


  frameHelmTurnState
    .renderApplication();


  return result;
}


export function setFrameHelmTurnSpeed(
  speed
) {
  const result =
    frameHelmTurnState
      .ensureTurn()
      .setSpeed(
        speed
      );


  frameHelmTurnState
    .renderApplication();


  return result;
}


/* ============================================================
   Turn Overcharge commands
   ============================================================ */

export function useFrameHelmTurnOvercharge(
  options
) {
  const result =
    frameHelmTurnState
      .ensureTurn()
      .useOvercharge(
        options
      );


  frameHelmTurnState
    .renderApplication();


  return result;
}

